const texto = $input.first().json.data || '';
const linhas = texto.split(/\r?\n/).filter(l => l.trim() !== '');
const cabecalho = linhas.shift().split(',').map(c => c.trim().toLowerCase());

return linhas.map(linha => {
  const valores = linha.split(',').map(v => v.trim());
  const reg = {};
  cabecalho.forEach((c, i) => { reg[c] = valores[i]; });
  return { json: {
    perfil: reg.perfil,
    produto: reg.produto,
    minimo: Number(reg.minimo),
    rentabilidade: Number(reg.rentabilidade)
  }};
});

// Separa os itens que vieram do webhook e os produtos do CSV
const itens = $input.all().map(i => i.json);
const origem = itens.find(i => i.body && Array.isArray(i.body.clientes));
const clientes = origem ? origem.body.clientes : [];
const produtos = itens.filter(i => i.produto);

const moeda = v => Number(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const estilos = ['amigavel', 'objetivo', 'consultivo'];

// Tres modelos fixos, alternados entre os clientes para nao repetir o texto
const modelos = [
  (c, p) => `Ola, ${c.nome}! Com o perfil ${c.perfil} e saldo de ${moeda(c.saldo)}, uma opcao para voce conhecer e ${p.produto}, com aplicacao minima de ${moeda(p.minimo)} e rentabilidade de referencia de ${p.rentabilidade}% ao ano.`,
  (c, p) => `${c.nome}, separamos uma sugestao alinhada ao seu perfil ${c.perfil}: ${p.produto}. Entrada a partir de ${moeda(p.minimo)}; rentabilidade de referencia de ${p.rentabilidade}% ao ano.`,
  (c, p) => `Prezado(a) ${c.nome}, avaliando seu saldo de ${moeda(c.saldo)}, o produto ${p.produto} se encaixa no perfil ${c.perfil}. Minimo de ${moeda(p.minimo)} e rentabilidade de referencia de ${p.rentabilidade}% ao ano.`
];
const aviso = ' Rentabilidade passada nao garante resultados futuros.';

return clientes.map((c, idx) => {
  const perfil = String(c.perfil || '').trim().toLowerCase();
  const saldo = Number(c.saldo) || 0;
  const candidatos = produtos.filter(p => String(p.perfil).toLowerCase() === perfil);
  // Escolhe o produto de maior rentabilidade que o saldo permite
  const elegiveis = candidatos.filter(p => saldo >= p.minimo)
                              .sort((a, b) => b.rentabilidade - a.rentabilidade);
  const produto = elegiveis[0];

  let mensagem;
  if (!produto) {
    const menor = candidatos.sort((a, b) => a.minimo - b.minimo)[0];
    mensagem = menor
      ? `Ola, ${c.nome}! Seu saldo atual ainda esta abaixo do minimo de ${moeda(menor.minimo)} para ${menor.produto}. Quando for possivel, vale reavaliar.`
      : `Ola, ${c.nome}! Ainda nao ha produto cadastrado para o perfil ${c.perfil}.`;
  } else {
    mensagem = modelos[idx % modelos.length](c, produto) + aviso;
  }

  return { json: {
    nome: c.nome,
    email: c.email,
    saldo,
    perfil: c.perfil,
    produto: produto ? produto.produto : null,
    minimo: produto ? produto.minimo : null,
    rentabilidade: produto ? produto.rentabilidade : null,
    estilo: estilos[idx % estilos.length],
    mensagem_estatica: mensagem
  }};
});

