  subject: conteudo.assunto || 'Uma sugestao de investimento para o seu perfil',
  html: conteudo.corpo_html || `<p>${base.mensagem_estatica}</p>`,
  origem_texto: conteudo.corpo_html ? 'llm' : 'fallback_estatico'
}};

const itens = $input.all().map(i => i.json);
const enviados = itens.filter(i => i.id && i.threadId).length;
const falhasEnvio = itens.filter(i => i.error).length;
const invalidos = itens.filter(i => i.status === 'email_invalido').map(i => i.nome);
return [{ json: {
  status: 'concluido',
  total: itens.length,
  enviados,
  falhas_envio: falhasEnvio,
  emails_invalidos: invalidos
}}];
